UNITS = [
 {"id": "PEDS-U295", "ch": 35, "n": 1, "title": "Nephrotic Syndrome — Features", "sec": "Nephrotic features · p157", "qs": ["PEDS-C35-001", "PEDS-C35-002", "PEDS-C35-003", "PEDS-C35-004", "PEDS-C35-005", "PEDS-C35-006", "PEDS-C35-007", "PEDS-C35-008", "PEDS-C35-009", "PEDS-C35-010"], "guide": "1. massive proteinuria (hall mark): excretion > 40 mg/m2/hr or > 1 g/m2/day; spot dipstick 3+/4+; P:C ratio > 2. 2. hypoalbuminemia (serum albumin < 3 g/dl) → ↓ oncotic pressure. 3. anasarca. 4. hyperlipidemia (d/t ↑ production of lipoprotein and lipid by liver)."},
 {"id": "PEDS-U296", "ch": 35, "n": 2, "title": "Nephrotic Syndrome — Pathology & MCD Management", "sec": "Pathology & MCD · p157", "qs": ["PEDS-C35-011", "PEDS-C35-012", "PEDS-C35-013", "PEDS-C35-014", "PEDS-C35-015", "PEDS-C35-016", "PEDS-C35-017", "PEDS-C35-018", "PEDS-C35-019", "PEDS-C35-020", "PEDS-C35-021", "PEDS-C35-022", "PEDS-C35-023", "PEDS-C35-024"], "guide": "MCD: m/c. Significant glomerular lesions: FSGS, mesangial proliferative glomerulonephropathy, C3 glomerulopathy. MCD pathogenesis: effacement of negatively charged foot process of podocyte → negatively-charged protein not repelled → ↑ protein excretion. Management: diet (high protein, no added salt); prednisolone 2 mg/kg/day daily (upto 60 mg) × 6 weeks then 1.5 mg/kg/day alternate days (upto 40 mg) × 6 weeks; response (confirms MCD without biopsy): urine protein < 4 mg/m2/hr or dipstick nil/trace; P:C ratio < 0.2; diuretic for significant edema: furosemide → if no response add spironolactone."},
 {"id": "PEDS-U297", "ch": 35, "n": 3, "title": "Nephrotic Syndrome — Course, Relapse & Resistance", "sec": "Course of disease · p158", "qs": ["PEDS-C35-025", "PEDS-C35-026", "PEDS-C35-027", "PEDS-C35-028", "PEDS-C35-029", "PEDS-C35-030", "PEDS-C35-031", "PEDS-C35-032", "PEDS-C35-033", "PEDS-C35-034", "PEDS-C35-035", "PEDS-C35-036", "PEDS-C35-037", "PEDS-C35-038"], "guide": "Course: presentation → remission / relapse (recurrence of proteinuria; daily steroids 2 mg/kg/day → alternate day 1.5 mg/kg/day; continue 4 weeks; relapse during alternate-day therapy or relapse within 14 d of stoppage = steroid dependence). Frequent relapses: ≥ 2 relapses in 6 months OR ≥ 3 relapses in 1 year. Management: avoid steroids (toxicity); immunomodulatory: levamisole, mycophenolate. Steroid resistant NS: usually d/t significant glomerular lesions / congenital NS (onset > 3 months). Investigations: renal biopsy, GFR estimation, genetic testing — NPHS1 (Finnish type; nephrin; AR), NPHS2 (podocin; AR), WT1 (Denys-Drash; AD; ↑ Wilms risk, ambiguous genitalia in male). Management: calcineurin inhibitors (cyclosporin, tacrolimus)."},
 {"id": "PEDS-U298", "ch": 35, "n": 4, "title": "Complications of Nephrotic Syndrome", "sec": "Complications · p159", "qs": ["PEDS-C35-039", "PEDS-C35-040", "PEDS-C35-041", "PEDS-C35-042", "PEDS-C35-043", "PEDS-C35-044", "PEDS-C35-045", "PEDS-C35-046", "PEDS-C35-047", "PEDS-C35-048", "PEDS-C35-049", "PEDS-C35-050"], "guide": "Proteinuria of → ↓ immunoglobulins/complement proteins → impaired opsonization → ↑ risk of encapsulated bacterial infections (Streptococcus pneumoniae, Haemophilus influenzae type B) → spontaneous bacterial peritonitis (SBP), cellulitis, pneumonia. Also: ↓ anticoagulant proteins (Protein C / Protein S) + ↑ fibrinogen production in liver → hypercoagulability → infarctions (eg: stroke)."},
 {"id": "PEDS-U299", "ch": 35, "n": 5, "title": "Nephritic Syndrome Glomerulonephritis — Features", "sec": "Nephritic features · p159", "qs": ["PEDS-C35-051", "PEDS-C35-052", "PEDS-C35-053", "PEDS-C35-054", "PEDS-C35-055", "PEDS-C35-056", "PEDS-C35-057", "PEDS-C35-058", "PEDS-C35-059", "PEDS-C35-060", "PEDS-C35-061", "PEDS-C35-062"], "guide": "Clinical features: hematuria (hall mark; cola-colored urine; urine microscopy: > 5 RBC/hpf, dysmorphic RBC, RBC casts); oliguria; localized edema (eg: periorbital puffiness of eyes); hypertension (HTN); mild proteinuria. Diseases seen: post-streptococcal glomerulonephritis, IgA nephropathy, hereditary nephritis."},
 {"id": "PEDS-U300", "ch": 35, "n": 6, "title": "PSGN — Pathogenesis & Lag Period", "sec": "PSGN · p159", "qs": ["PEDS-C35-063", "PEDS-C35-064", "PEDS-C35-065", "PEDS-C35-066", "PEDS-C35-067", "PEDS-C35-068", "PEDS-C35-069", "PEDS-C35-070", "PEDS-C35-071", "PEDS-C35-072"], "guide": "Post-infectious phenomenon; course 7–10 days; pathogenesis: Group A β hemolytic streptococci. Initial infection (pharyngitis/pyoderma) → formation of immune complexes → deposited in kidney → nephritis. Lag period: 1–2 wks: pharyngitis (M4, M12 strains); 3–6 wks: pyoderma (M49 strain)."},
 {"id": "PEDS-U301", "ch": 35, "n": 7, "title": "PSGN — Clinical, Investigations & Management", "sec": "PSGN clinical/investigations · p160", "qs": ["PEDS-C35-073", "PEDS-C35-074", "PEDS-C35-075", "PEDS-C35-076", "PEDS-C35-077", "PEDS-C35-078", "PEDS-C35-079", "PEDS-C35-080", "PEDS-C35-081", "PEDS-C35-082", "PEDS-C35-083", "PEDS-C35-084", "PEDS-C35-085", "PEDS-C35-086", "PEDS-C35-087", "PEDS-C35-088"], "guide": "Incidence: m/c age 5–15 years (school-going); male > female. Presentation: abrupt onset hematuria, oliguria, edema, HTN; preceding h/o infection not requisite for diagnosis; degree of oliguria decides severity. Complications: hypertensive encephalopathy (seizures), left ventricular failure. Investigations: antibody titre (ASO; anti-DNAase B additionally in skin infection); serum C3 ↓ in immune complex-mediated disorders, normalises within 8–12 weeks; renal biopsy not routinely — indications: persistent low C3 > 12 weeks, systemic illness (high fever, rash, joint pain), no resolution > 10 days. Findings: EM sub-epithelial immune complex deposits → humps; IF IgG + C3 in capillary walls and mesangium → starry sky appearance. Management: self-limiting; supportive for HTN (amlodipine, nifedipine); no prophylactic role of antibiotics (unlike rheumatic fever)."},
 {"id": "PEDS-U302", "ch": 35, "n": 8, "title": "IgA Nephropathy (Berger's Disease)", "sec": "IgA nephropathy · p160–161", "qs": ["PEDS-C35-089", "PEDS-C35-090", "PEDS-C35-091", "PEDS-C35-092", "PEDS-C35-093", "PEDS-C35-094", "PEDS-C35-095", "PEDS-C35-096", "PEDS-C35-097", "PEDS-C35-098", "PEDS-C35-099", "PEDS-C35-100"], "guide": "Berger's disease: m/c cause of chronic and recurrent nephritis (associated with CKD). Pathogenesis: any viral/bacterial URTI → IgA in mesangium and capillary walls. Investigations: C3 normal; ASO titre no increase; renal biopsy mesangial proliferation + IgA deposits. Management: chronic nephropathy (constant follow-up) → 10–20% cases → CKD; ACE inhibitors/ARB → ↓ renal progression → ↓ CKD risk; fish oil (omega-3 PUFA) → ↓ macrophage entry into mesangium → no initiating factors for IgA deposition."},
 {"id": "PEDS-U303", "ch": 35, "n": 9, "title": "Hereditary Nephritis (Alport Syndrome)", "sec": "Hereditary nephritis · p161", "qs": ["PEDS-C35-101", "PEDS-C35-102", "PEDS-C35-103", "PEDS-C35-104", "PEDS-C35-105", "PEDS-C35-106", "PEDS-C35-107", "PEDS-C35-108", "PEDS-C35-109", "PEDS-C35-110", "PEDS-C35-111", "PEDS-C35-112", "PEDS-C35-113", "PEDS-C35-114"], "guide": "AKA Alport syndrome. m/c inheritance: X-linked dominant. Genetic defect: COL4A5 gene (α5 chain of type IV collagen). Clinical: triad — hematuria, high-frequency sensorineural hearing loss, ocular findings (anterior lenticonus = diagnostic, macular flecks, corneal erosions). Investigations: COL4A5 gene testing; renal biopsy: lamellations (basket weave), thinning + thickening of GBM. Management: regular follow-up (many develop ESRD by 2nd–3rd decade); supportive; ACE inhibitors → ↓ renal progression."},
]

