 {"id": "PEDS-C35-042", "sec": "NS complications", "page": 159, "q": "Spontaneous bacterial peritonitis (SBP) is a complication of nephrotic syndrome.", "opts": ["True", "False"], "ans": 0, "exp": "True — with cellulitis and pneumonia (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-043", "sec": "NS complications", "page": 159, "q": "The hypercoagulability in nephrotic syndrome is due to —", "opts": ["A fall of plasma fibrinogen only in serum", "An isolated rise of hepatic Protein C only", "A platelet increase as the single cause", "↓ Protein C and Protein S plus ↑ hepatic fibrinogen production"], "ans": 3, "exp": "↓ anticoagulant proteins (Protein C / Protein S) + ↑ production of fibrinogen in liver (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-044", "sec": "NS complications", "page": 159, "q": "Hypercoagulability in nephrotic syndrome can cause —", "opts": ["Infarctions and manifestations such as stroke", "Petechiae only without any infarcts", "Glycosuria only in the spot urine", "Asthma attacks triggered by the cold"], "ans": 0, "exp": "Hypercoagulability → infarctions and manifestations (eg: stroke) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-045", "sec": "NS complications", "page": 159, "q": "Protein C and Protein S in nephrotic syndrome are —", "opts": ["Liver enzymes", "Anticoagulant proteins that are decreased", "Procoagulant proteins that increase", "Clotting factors from the spleen"], "ans": 1, "exp": "↓ anticoagulant proteins (Protein C / Protein S) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-046", "sec": "NS complications", "page": 159, "q": "Match the nephrotic complication pathway — select the correct combination:", "pairs": [["Proteinuria", "Hypercoagulability with stroke and infarctions"], ["↓ Immunoglobulins and complement", "↓ Immunoglobulins and complement"], ["Encapsulated bacterial infections", "Impaired opsonization"], ["↓ Protein C/S with ↑ fibrinogen", "SBP, cellulitis, pneumonia"]], "opts": ["A-3, B-2, C-1, D-4", "A-2, B-3, C-4, D-1", "A-4, B-1, C-3, D-2", "A-4, B-1, C-2, D-3"], "ans": 1, "exp": "Correct pairs: Proteinuria→↓ Immunoglobulins and complement; ↓ Immunoglobulins and complement→Impaired opsonization; Encapsulated bacterial infections→SBP, cellulitis, pneumonia; ↓ Protein C/S with ↑ fibrinogen→Hypercoagulability with stroke and infarctions. (Book p159)", "type": "match"},
 {"id": "PEDS-C35-047", "sec": "NS complications", "page": 159, "q": "Odd one out (infections in nephrotic syndrome):", "opts": ["Spontaneous bacterial peritonitis", "Cellulitis", "Pneumonia", "Meningococcal septicemia only"], "ans": 3, "exp": "SBP, cellulitis and pneumonia are listed; the encapsulated organisms are pneumococcus and H. influenzae type B, not meningococcus (Book p159)", "type": "odd"},
 {"id": "PEDS-C35-048", "sec": "NS complications", "page": 159, "stem": "A boy with nephrotic syndrome develops fever, abdominal pain and tenderness; ascitic fluid culture grows Streptococcus pneumoniae.", "q": "The complication is —", "opts": ["Spontaneous bacterial peritonitis (SBP)", "Hypertensive encephalopathy", "Acute appendicitis", "Intussusception"], "ans": 0, "exp": "SBP with encapsulated organisms (pneumococcus) is a classic NS complication (Book p159)", "type": "case"},
 {"id": "PEDS-C35-049", "sec": "NS complications", "page": 159, "q": "Nephrotic syndrome increases the risk of thromboembolism because fibrinogen falls.", "opts": ["True", "False"], "ans": 1, "exp": "False — fibrinogen production in the liver increases (with ↓ Protein C/S), causing hypercoagulability (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-050", "sec": "NS complications", "page": 159, "q": "The fibrinogen production in the liver in nephrotic syndrome is —", "opts": ["Unchanged", "Absent", "Increased", "Decreased"], "ans": 2, "exp": "↑ production of fibrinogen in liver (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-051", "sec": "Nephritic features", "page": 159, "q": "The hallmark of nephritic syndrome glomerulonephritis is —", "opts": ["Massive proteinuria", "Hypoalbuminemia", "Hyperlipidemia", "Hematuria"], "ans": 3, "exp": "Hematuria: hall mark (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-052", "sec": "Nephritic features", "page": 159, "q": "The urine in nephritic syndrome is classically —", "opts": ["Cola-colored", "Straw-colored and clear", "Frothy and pale", "Milky white"], "ans": 0, "exp": "Cola-colored urine (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-053", "sec": "Nephritic features", "page": 159, "q": "Urine microscopy in nephritic syndrome shows —", "opts": ["Just 1–2 normal RBC per high power field", "> 5 RBC/hpf with dysmorphic RBC and RBC casts", "> 5 WBC/hpf without any casts at all", "Only glucose and ketones on the strip"], "ans": 1, "exp": "> 5 RBC/hpf, dysmorphic RBC, RBC casts (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-054", "sec": "Nephritic features", "page": 159, "q": "The edema in nephritic syndrome is classically —", "opts": ["Only in the legs at the end of the day", "Absent in every child with nephritis", "Localized (e.g., periorbital puffiness of eyes)", "Generalized anasarca over the whole body"], "ans": 2, "exp": "Localized edema eg: periorbital (puffiness of eyes) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-055", "sec": "Nephritic features", "page": 159, "q": "The proteinuria in nephritic syndrome is ___.", "opts": ["Massive (> 40 mg/m2/hr)", "Always absent", "Only at night", "Mild"], "ans": 3, "exp": "Mild proteinuria (Book p159)", "type": "fill"},
 {"id": "PEDS-C35-056", "sec": "Nephritic features", "page": 159, "q": "Which of the following is a disease seen in nephritic syndrome glomerulonephritis?", "opts": ["Post-streptococcal glomerulonephritis", "Minimal change disease", "Horseshoe kidney", "Posterior urethral valve"], "ans": 0, "exp": "Diseases seen: post-streptococcal GN, IgA nephropathy, hereditary nephritis (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-057", "sec": "Nephritic features", "page": 159, "q": "Match the nephritic feature with its detail — select the correct combination:", "pairs": [["Hematuria", "periorbital puffiness"], ["Localized edema", "cola-colored urine"], ["Urine microscopy", "mild"], ["Proteinuria", "RBC casts + dysmorphic RBC (> 5 RBC/hpf)"]], "opts": ["A-2, B-4, C-3, D-1", "A-1, B-3, C-4, D-2", "A-4, B-2, C-1, D-3", "A-2, B-1, C-4, D-3"], "ans": 3, "exp": "Correct pairs: Hematuria→cola-colored urine; Localized edema→periorbital puffiness; Urine microscopy→RBC casts + dysmorphic RBC (> 5 RBC/hpf); Proteinuria→mild. (Book p159)", "type": "match"},
 {"id": "PEDS-C35-058", "sec": "Nephritic features", "page": 159, "q": "Oliguria is a clinical feature of nephritic syndrome.", "opts": ["True", "False"], "ans": 0, "exp": "True — oliguria is one of the five nephritic features (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-059", "sec": "Nephritic features", "page": 159, "q": "The proteinuria of nephritic syndrome is massive.", "opts": ["True", "False"], "ans": 1, "exp": "False — it is mild; massive proteinuria is the nephrotic hallmark (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-060", "sec": "Nephritic features", "page": 159, "q": "Odd one out (nephritic syndrome features):", "opts": ["Hypoalbuminemia with anasarca", "Hematuria with cola-colored urine", "Oliguria with fluid retention", "Hypertension with fluid overload"], "ans": 0, "exp": "Hematuria, oliguria, localized edema, HTN and mild proteinuria are nephritic; hypoalbuminemia with anasarca is nephrotic (Book p157, 159)", "type": "odd"},
 {"id": "PEDS-C35-061", "sec": "Nephritic features", "page": 159, "q": "RBC casts in urine are a feature of nephritic rather than nephrotic syndrome.", "opts": ["True", "False"], "ans": 0, "exp": "True — urine microscopy in nephritic GN shows RBC casts (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-062", "sec": "Nephritic features", "page": 159, "stem": "A 7-year-old boy presents with abrupt cola-colored urine, periorbital puffiness, blood pressure 140/90 and oliguria; urine shows dysmorphic RBCs and RBC casts.", "q": "The syndrome is —", "opts": ["Posterior urethral valve", "Minimal change disease", "Nephritic syndrome", "Nephrotic syndrome"], "ans": 2, "exp": "Hematuria + oliguria + localized edema + HTN + RBC casts = nephritic syndrome (Book p159)", "type": "case"},
 {"id": "PEDS-C35-063", "sec": "PSGN", "page": 159, "q": "PSGN is a ___ phenomenon.", "opts": ["congenital", "neoplastic", "metabolic", "post-infectious"], "ans": 3, "exp": "Post-infectious phenomenon (Book p159)", "type": "fill"},
 {"id": "PEDS-C35-064", "sec": "PSGN", "page": 159, "q": "The course of PSGN is —", "opts": ["7–10 days", "7–10 weeks", "7–10 months", "Lifelong without treatment"], "ans": 0, "exp": "Course: 7–10 days (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-065", "sec": "PSGN", "page": 159, "q": "The pathogenic organism in PSGN is —", "opts": ["E. coli", "Group A β hemolytic streptococci", "Group B streptococci", "Staphylococcus aureus"], "ans": 1, "exp": "Pathogenesis: Group A β hemolytic streptococci (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-066", "sec": "PSGN", "page": 159, "q": "The initial infection in PSGN may be —", "opts": ["Sinusitis only", "Pneumonia only", "Pharyngitis or pyoderma", "Otitis media only"], "ans": 2, "exp": "Initial infection (pharyngitis/pyoderma) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-067", "sec": "PSGN", "page": 159, "q": "In PSGN pathogenesis, immune complexes are —", "opts": ["Degraded in the liver and cause no harm", "Deposited only in the skin of the child", "Never formed in post-infectious states", "Formed and deposited in the kidney, causing nephritis"], "ans": 3, "exp": "Formation of immune complexes → deposited in kidney → nephritis (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-068", "sec": "PSGN", "page": 159, "q": "After pharyngitis, the lag period to PSGN is —", "opts": ["1–2 weeks (M4, M12 strains)", "3–6 weeks (M49 strain)", "4–6 months", "1–2 days"], "ans": 0, "exp": "Lag period: 1–2 wks: pharyngitis (M4, M12 strains) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-069", "sec": "PSGN", "page": 159, "q": "After pyoderma, the lag period to PSGN is —", "opts": ["10 days exactly", "3–6 weeks (M49 strain)", "1–2 weeks (M4, M12 strains)", "6–12 months"], "ans": 1, "exp": "3 to 6 wks: pyoderma (M49 strain) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-070", "sec": "PSGN", "page": 159, "q": "Match the PSGN lag period detail — select the correct combination:", "pairs": [["Pharyngitis", "3–6 week lag period"], ["Pyoderma", "Pyoderma-associated strain"], ["M4 and M12 strains", "1–2 week lag period"], ["M49 strain", "Pharyngitis-associated strains"]], "opts": ["A-2, B-1, C-4, D-3", "A-2, B-1, C-3, D-4", "A-3, B-1, C-4, D-2", "A-3, B-4, C-2, D-1"], "ans": 2, "exp": "Correct pairs: Pharyngitis→1–2 week lag period; Pyoderma→3–6 week lag period; M4 and M12 strains→Pharyngitis-associated strains; M49 strain→Pyoderma-associated strain. (Book p159)", "type": "match"},
 {"id": "PEDS-C35-071", "sec": "PSGN", "page": 159, "q": "PSGN follows pharyngitis sooner than it follows pyoderma.", "opts": ["True", "False"], "ans": 0, "exp": "True — 1–2 weeks after pharyngitis vs 3–6 weeks after pyoderma (Book p159)", "type": "tf"},
 {"id": "PEDS-C35-072", "sec": "PSGN", "page": 159, "q": "The M49 strain of streptococcus is associated with PSGN after —", "opts": ["Pyoderma", "Pharyngitis", "Otitis media", "Dental infection"], "ans": 0, "exp": "3 to 6 wks: pyoderma (M49 strain) (Book p159)", "type": "mcq"},
 {"id": "PEDS-C35-073", "sec": "PSGN clinical", "page": 160, "q": "The most common age group for PSGN is —", "opts": ["Adolescents (16–25 years)", "5–15 years (school-going child)", "Infants (< 1 year)", "Elderly (> 60 years)"], "ans": 1, "exp": "m/c age group: 5–15 years (school-going child) (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-074", "sec": "PSGN clinical", "page": 160, "q": "The sex incidence of PSGN is —", "opts": ["Equal in both sexes", "Only in males", "Male > female", "Female > male"], "ans": 2, "exp": "Male > female (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-075", "sec": "PSGN clinical", "page": 160, "q": "PSGN presents with abrupt onset of —", "opts": ["Only watery diarrhea without urine change", "Only jaundice with a normal urine output", "Only seizures without any hypertension", "Hematuria, oliguria, edema and HTN"], "ans": 3, "exp": "Abrupt onset of hematuria, oliguria, edema and HTN (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-076", "sec": "PSGN clinical", "page": 160, "q": "A preceding history of infection for diagnosing PSGN is —", "opts": ["Not requisite", "Always required", "Only required in pyoderma", "Only required in girls"], "ans": 0, "exp": "Preceding h/o infection not requisite for diagnosis (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-077", "sec": "PSGN clinical", "page": 160, "q": "In PSGN, the disease severity is decided by the —", "opts": ["Size of the kidneys", "Degree of oliguria", "Degree of proteinuria", "Height of fever"], "ans": 1, "exp": "Degree of oliguria decides disease severity (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-078", "sec": "PSGN clinical", "page": 160, "q": "The complications of PSGN include —", "opts": ["Cleft palate detected on mouth examination", "Hypothyroidism with a slow heart rate", "Hypertensive encephalopathy (seizures) and left ventricular failure", "New-onset diabetes mellitus of the young"], "ans": 2, "exp": "Complications: hypertensive encephalopathy: seizures; left ventricular failure (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-079", "sec": "PSGN investigations", "page": 160, "q": "The antibody titre estimated in PSGN includes —", "opts": ["Anti-nuclear antibody only", "Anti-DNA antibody only", "Anti-CCP only", "Anti-Streptolysin O (ASO)"], "ans": 3, "exp": "Antibody titre: ASO (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-080", "sec": "PSGN investigations", "page": 160, "q": "Anti-DNAase B titre is additionally used in PSGN after —", "opts": ["Skin infection", "Pharyngitis only", "Otitis media", "Sinusitis"], "ans": 0, "exp": "Anti-DNAase B (additionally in skin infection) (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-081", "sec": "PSGN investigations", "page": 160, "q": "In PSGN, the serum C3 level is —", "opts": ["Zero at presentation in every single case", "Decreased (normalises within 8–12 weeks)", "Elevated permanently without any recovery", "Always normal at the time of presentation"], "ans": 1, "exp": "↓ in immune complex-mediated disorders; value usually normalises within 8–12 weeks (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-082", "sec": "PSGN investigations", "page": 160, "q": "Renal biopsy in PSGN is —", "opts": ["Done at birth", "Only in females", "Not performed routinely", "Mandatory in every child"], "ans": 2, "exp": "Renal biopsy: not performed routinely (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-083", "sec": "PSGN investigations", "page": 160, "q": "An indication for renal biopsy in PSGN is —", "opts": ["Being in the 5–15 year age group only", "Mild hematuria that is otherwise unremarkable", "A normal C3 level at the first visit", "Persistent low C3 for > 12 weeks (to rule out other causes)"], "ans": 3, "exp": "Indications: persistent low C3 > 12 weeks; systemic illness (high fever, rash, joint pain); no resolution > 10 days (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-084", "sec": "PSGN investigations", "page": 160, "q": "On electron microscopy, PSGN shows sub-epithelial immune complex deposits called ___.", "opts": ["Humps", "Whorls", "Tubules", "Cysts"], "ans": 0, "exp": "EM: sub-epithelial immune complexes deposits → humps (Book p160)", "type": "fill"},
 {"id": "PEDS-C35-085", "sec": "PSGN investigations", "page": 160, "q": "On immunofluorescence, IgG + C3 deposition in capillary walls and mesangium gives the —", "opts": ["Snowman appearance", "Starry sky appearance", "Foot process appearance", "Basket weave appearance"], "ans": 1, "exp": "IF: IgG + C3 deposition → starry sky appearance (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-086", "sec": "PSGN management", "page": 160, "q": "PSGN is managed as a —", "opts": ["Life-long immunosuppressed state", "Dialysis-first condition", "Self-limiting condition (supportive)", "Surgical emergency"], "ans": 2, "exp": "Management: self-limiting condition (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-087", "sec": "PSGN management", "page": 160, "q": "The supportive drugs for HTN in PSGN are —", "opts": ["Digoxin, furosemide", "Morphine, atropine", "Aspirin, warfarin", "Amlodipine, nifedipine"], "ans": 3, "exp": "Supportive management for HTN: amlodipine, nifedipine (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-088", "sec": "PSGN management", "page": 160, "q": "Unlike rheumatic fever, in PSGN there is —", "opts": ["No prophylactic role of antibiotics", "A mandatory penicillin course", "A vaccine given", "A 10-day aspirin course"], "ans": 0, "exp": "No prophylactic role of antibiotics (unlike rheumatic fever) (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-089", "sec": "IgA nephropathy", "page": 160, "q": "IgA nephropathy is also known as —", "opts": ["Potter's syndrome", "Berger's disease", "Alport syndrome", "Denys-Drash syndrome"], "ans": 1, "exp": "IgA Nephropathy: (Berger's disease) (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-090", "sec": "IgA nephropathy", "page": 160, "q": "IgA nephropathy is the most common cause of —", "opts": ["Posterior urethral valve in male children", "Bilateral renal agenesis with no urine", "Chronic and recurrent nephritis (associated with CKD)", "Nephrotic syndrome in every affected child"], "ans": 2, "exp": "m/c cause of chronic and recurrent nephritis (associated with CKD) (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-091", "sec": "IgA nephropathy", "page": 160, "q": "The pathogenesis of IgA nephropathy is triggered by —", "opts": ["Group A β hemolytic streptococci only", "A diet that is high in added salt", "Trauma to the renal parenchyma region", "Any viral or bacterial upper respiratory tract infection"], "ans": 3, "exp": "Any viral/bacterial URTI → IgA in mesangium and capillary walls (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-092", "sec": "IgA nephropathy", "page": 160, "q": "In IgA nephropathy, IgA deposits are found in the —", "opts": ["Mesangium and capillary walls", "Renal pelvis only", "Ureter only", "Bladder mucosa only"], "ans": 0, "exp": "IgA in mesangium and capillary walls (Book p160)", "type": "mcq"},
 {"id": "PEDS-C35-093", "sec": "IgA nephropathy", "page": 161, "q": "The C3 level in IgA nephropathy is —", "opts": ["Markedly elevated", "Normal", "Low permanently", "Zero"], "ans": 1, "exp": "C3 levels: normal (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-094", "sec": "IgA nephropathy", "page": 161, "q": "The ASO titre in IgA nephropathy shows —", "opts": ["A fall to zero", "An oscillating pattern", "No increase", "A marked rise"], "ans": 2, "exp": "ASO titre: no increase (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-095", "sec": "IgA nephropathy", "page": 161, "q": "The renal biopsy in IgA nephropathy shows —", "opts": ["Sub-epithelial humps on electron microscopy", "Basket weave GBM on the renal biopsy", "Cysts scattered through both cortices", "Mesangial proliferation with IgA deposits"], "ans": 3, "exp": "Renal biopsy: mesangial proliferation + IgA deposits (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-096", "sec": "IgA nephropathy", "page": 161, "q": "In chronic nephropathy (IgA), ___ of cases progress to chronic kidney disease.", "opts": ["10–20%", "90–100%", "1–2%", "Exactly 50%"], "ans": 0, "exp": "Chronic nephropathy (requires constant follow-up) → 10–20% cases → CKD (Book p161)", "type": "fill"},
 {"id": "PEDS-C35-097", "sec": "IgA nephropathy", "page": 161, "q": "ACE inhibitors/ARB in IgA nephropathy —", "opts": ["Prevent all future upper respiratory infections", "Slow renal progression and lower the risk of CKD", "Cure the disease in every single case", "Raise the serum C3 level back to normal"], "ans": 1, "exp": "ACE inhibitors/ARB → ↓ renal progression → ↓ risk of CKD (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-098", "sec": "IgA nephropathy", "page": 161, "q": "Fish oil (omega-3 PUFA) in IgA nephropathy works by —", "opts": ["Blocking the synthesis of complement C3 protein in the liver", "Curing the upper respiratory infection itself permanently", "Reducing macrophage entry into the mesangium, removing IgA deposition triggers", "Raising the ASO titre to a protective level at all times"], "ans": 2, "exp": "Fish oil (Omega 3 PUFA) → ↓ macrophage entry into mesangium → no initiating factors for IgA deposition (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-099", "sec": "IgA nephropathy", "page": 161, "q": "In IgA nephropathy, the C3 level is low like in PSGN.", "opts": ["True", "False"], "ans": 1, "exp": "False — C3 is normal in IgA nephropathy; it is low in PSGN (Book p160–161)", "type": "tf"},
 {"id": "PEDS-C35-100", "sec": "IgA nephropathy", "page": 161, "stem": "A 12-year-old boy has recurrent cola-colored urine after each throat infection; ASO is not raised and C3 is normal; biopsy shows mesangial IgA deposits.", "q": "The diagnosis is —", "opts": ["IgA nephropathy (Berger's disease)", "Post-streptococcal glomerulonephritis", "Alport syndrome with collagen defect", "Minimal change disease with no biopsy"], "ans": 0, "exp": "Recurrent nephritis after URTI + normal C3/ASO + mesangial IgA = Berger's disease (Book p160–161)", "type": "case"},
 {"id": "PEDS-C35-101", "sec": "Hereditary nephritis", "page": 161, "q": "Hereditary nephritis is also known as —", "opts": ["Denys-Drash syndrome", "Alport syndrome", "Berger's disease", "Potter's syndrome"], "ans": 1, "exp": "AKA Alport syndrome (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-102", "sec": "Hereditary nephritis", "page": 161, "q": "The most common mode of inheritance in Alport syndrome is —", "opts": ["Autosomal dominant", "X-linked recessive", "X-linked dominant", "Autosomal recessive"], "ans": 2, "exp": "m/c mode of inheritance: X-linked dominant (Book p161)", "type": "mcq"},
 {"id": "PEDS-C35-103", "sec": "Hereditary nephritis", "page": 161, "q": "The genetic defect in Alport syndrome is the ___ gene.", "opts": ["PKHD1", "NPHS1", "WT1", "COL4A5"], "ans": 3, "exp": "Genetic defect: COL4A5 gene (Book p161)", "type": "fill"},
